<script setup lang="ts">
definePageMeta({ middleware: 'admin-auth' }); const navigationOpen = ref(false); const search = ref(''); const selectedStatus = ref('all'); const selectedType = ref('all'); const { getAdminGuides } = useAdminGuides(); const { data: guides, pending, error } = await useAsyncData('admin-guides', getAdminGuides)
const title = (guide: NonNullable<typeof guides.value>[number]) => guide.guide_translations.find(item => item.language_code === 'en')?.title ?? guide.guide_translations[0]?.title ?? 'Untitled guide'; const types = computed(() => [...new Set((guides.value ?? []).map(guide => guide.guide_type))].sort()); const filtered = computed(() => (guides.value ?? []).filter((guide) => { const q = search.value.trim().toLowerCase(); return (!q || title(guide).toLowerCase().includes(q) || guide.slug.includes(q) || guide.guide_type.includes(q)) && (selectedStatus.value === 'all' || guide.status === selectedStatus.value) && (selectedType.value === 'all' || guide.guide_type === selectedType.value) })); const date = (value: string | null) => value ? new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(value)) : '—'
</script>
<template><div class="min-h-screen bg-slate-50 lg:pl-60"><AdminSidebar :open="navigationOpen" @close="navigationOpen = false" /><AdminHeader title="Guides" description="Manage practical Korea travel guidance." @menu="navigationOpen = true" /><main class="p-4 sm:p-6 lg:p-8"><section class="rounded-xl border border-slate-200 bg-white p-4 shadow-sm"><div class="mb-4 flex justify-end"><NuxtLink to="/admin/guides/new" class="rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white">Add guide</NuxtLink></div><div class="grid gap-3 md:grid-cols-[minmax(0,1fr)_11rem_11rem]"><input v-model="search" type="search" placeholder="Search by title, slug or type" class="rounded-lg border border-slate-300 px-3 py-2.5 text-sm"><select v-model="selectedStatus" class="rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm"><option value="all">All statuses</option><option value="published">Published</option><option value="draft">Draft</option><option value="archived">Archived</option></select><select v-model="selectedType" class="rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm"><option value="all">All types</option><option v-for="type in types" :key="type" :value="type">{{ type }}</option></select></div></section><p v-if="pending" class="mt-6 rounded-xl bg-white p-5 text-sm text-slate-500">Loading guides…</p><p v-else-if="error" class="mt-6 rounded-xl border border-red-200 bg-red-50 p-5 text-sm text-red-700">Guides are unavailable right now.</p><p v-else-if="!guides?.length" class="mt-6 rounded-xl border border-slate-200 bg-white p-5 text-sm text-slate-500">No guides have been added yet.</p><p v-else-if="!filtered.length" class="mt-6 rounded-xl border border-slate-200 bg-white p-5 text-sm text-slate-500">No guides match the current filters.</p><section v-else class="mt-6"><div class="hidden overflow-hidden rounded-xl border border-slate-200 bg-white lg:block"><table class="w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="px-5 py-3">Guide</th><th>Type</th><th>Featured</th><th>Status</th><th>Last verified</th><th>Updated</th><th class="px-5 text-right">Actions</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="guide in filtered" :key="guide.id"><td class="px-5 py-4"><p class="font-medium text-slate-900">{{ title(guide) }}</p><p class="text-xs text-slate-400">{{ guide.slug }}</p></td><td class="capitalize">{{ guide.guide_type }}</td><td>{{ guide.featured ? 'Yes' : '—' }}</td><td><AdminStatusBadge :status="guide.status" /></td><td>{{ date(guide.last_verified_at) }}</td><td>{{ date(guide.updated_at) }}</td><td class="px-5 text-right"><NuxtLink :to="`/admin/guides/${guide.id}`" class="font-medium text-slate-700">Edit</NuxtLink><NuxtLink v-if="guide.status === 'published'" :to="`/guides/${guide.slug}`" class="ml-4 font-medium text-blue-600">View</NuxtLink></td></tr></tbody></table></div><div class="grid gap-3 lg:hidden"><article v-for="guide in filtered" :key="guide.id" class="rounded-xl border border-slate-200 bg-white p-4"><div class="flex justify-between gap-3"><div><h2 class="font-semibold text-slate-900">{{ title(guide) }}</h2><p class="text-xs text-slate-400">{{ guide.slug }}</p></div><AdminStatusBadge :status="guide.status" /></div><p class="mt-3 text-sm text-slate-600 capitalize">{{ guide.guide_type }}<span v-if="guide.featured"> · Featured</span></p><div class="mt-4 flex gap-4 text-sm font-medium"><NuxtLink :to="`/admin/guides/${guide.id}`" class="text-slate-700">Edit</NuxtLink><NuxtLink v-if="guide.status === 'published'" :to="`/guides/${guide.slug}`" class="text-blue-600">View</NuxtLink></div></article></div></section></main></div></template>
